//! Exact identifier-artifact vectors generated by the pinned TypeScript reference.
//!
//! Every case re-derives its keys at the reference's own production Argon2 cost and compares the
//! event bytes and signatures byte for byte. Sealed salts cannot be pinned — a sealed box draws a
//! fresh ephemeral key per call — so each side's ciphertext is compared by what it opens to, and
//! the Rust side reseals recorded salts itself when a keeper must be reloaded.

use std::error::Error;

use keri_cesr::crypto::cipher::{Ciphertext, Decrypter, Encrypter};
use keri_cesr::crypto::salt::{Salt, SecurityTier};
use keri_cesr::crypto::verifier::KeyTransferability;
use keri_protocol::event::Timestamp;
use keri_protocol::prefix::IdentifierPrefix;
use keri_protocol::serialization::Sad;
use keri_protocol::threshold::SigningThreshold;
use keria_types::api::{Hab, KeyManagerState, KeyState, Role};
use serde::Deserialize;
use serde_json::Value;
use signify_keys::identifier::{
    CreateAlgorithm, CreateIdentifierRequest, IdentifierArtifact, IdentifierError, RotateIdentifierRequest,
    end_role_reply, incept_identifier, interact_identifier, location_scheme_reply, rotate_identifier, sign_reply,
};
use signify_keys::manager::{IdentifierKeeper, KeeperFactory, ManagerError};

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";
const FIXTURE: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/keri-aiding/v1.json"));

