fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(FIXTURE)?)
}

/// The controller salt one passcode derives, which every keeper of that client seals to.
fn controller_salt(bran: &str) -> Result<Salt, Box<dyn Error>> {
    Ok(Salt::from_qb64(&format!("0AA{}", &bran[..21]), SecurityTier::Low)?)
}

/// The sealing key pair the reference derives from the controller salt.
fn sealing_keys(bran: &str) -> Result<(Encrypter, Decrypter), Box<dyn Error>> {
    let signer = controller_salt(bran)?.derive_signer("", KeyTransferability::NonTransferable)?;
    Ok((
        Encrypter::from_verification_key(signer.verifier())?,
        Decrypter::from_signer(&signer),
    ))
}

fn factory(bran: &str) -> Result<KeeperFactory, Box<dyn Error>> {
    Ok(KeeperFactory::new(controller_salt(bran)?))
}

/// Compares an artifact's event and signatures with a recorded request.
fn assert_artifact_matches(artifact: &IdentifierArtifact, expected: &RequestRecord) -> Result<(), Box<dyn Error>> {
    assert_eq!(artifact.event.raw(), expected.event_raw.as_bytes());
    assert_eq!(artifact.signatures.qb64()?, expected.sigs);
    Ok(())
}

/// Compares a keeper's salty parameters with the recorded, sealed-salt-resolved ones.
fn assert_salty_params(keeper: &dyn IdentifierKeeper, bran: &str, expected: &Value) -> Result<(), Box<dyn Error>> {
    let KeyManagerState::Salty(salty) = keeper.parameters()? else {
        return Err("the keeper did not report salty parameters".into());
    };
    assert_eq!(
        Some(u64::from(salty.key_pair_index)),
        expected.get("pidx").and_then(Value::as_u64)
    );
    assert_eq!(
        Some(u64::from(salty.key_index)),
        expected.get("kidx").and_then(Value::as_u64)
    );
    assert_eq!(Some(salty.stem.as_str()), expected.get("stem").and_then(Value::as_str));
    assert_eq!(
        Some(salty.transferable),
        expected.get("transferable").and_then(Value::as_bool)
    );
    assert_eq!(
        Some(salty.inception_codes.len()),
        expected.get("icodes").and_then(Value::as_array).map(Vec::len)
    );
    assert_eq!(
        Some(salty.next_codes.len()),
        expected.get("ncodes").and_then(Value::as_array).map(Vec::len)
    );
    match expected.get("dcode").and_then(Value::as_str) {
        Some("B") => {
            // Pinned divergence: the reference stores the basic non-transferable prefix code as
            // the digest code for a non-transferable identifier. The digest list it would govern
            // is empty either way; Rust records the digest it actually uses.
            assert_eq!(salty.digest_code, "E");
        }
        recorded => assert_eq!(Some(salty.digest_code.as_str()), recorded),
    }

    // The sealed salt is compared by what it opens to, on both sides.
    let (_, decrypter) = sealing_keys(bran)?;
    let opened = decrypter.decrypt_salt(&Ciphertext::from_qb64(&salty.encrypted_salt)?, SecurityTier::Low)?;
    assert_eq!(
        Some(opened.expose_qb64()?.as_str()),
        expected.get("sxlt_opens_to").and_then(Value::as_str)
    );
    Ok(())
}

/// Rebuilds one creation case's request from its recorded name and provenance.
fn creation_request(fixture: &Fixture, case: &CreationCase) -> Result<CreateIdentifierRequest, Box<dyn Error>> {
    let salty = |passcode: &str, current: usize, next: usize| CreateAlgorithm::Salty {
        passcode: Some(passcode.into()),
        tier: SecurityTier::Low,
        current_count: current,
        next_count: next,
        cost: signify_keys::manager::DerivationCost::Production,
    };
    let mut request = match case.name.as_str() {
        "salty_default" | "salty_witnessed" | "salty_delegated_with_data" => {
            CreateIdentifierRequest::new(salty(&case.bran, 1, 1))
        }
        "salty_non_transferable" => {
            let mut request = CreateIdentifierRequest::new(salty(&case.bran, 1, 0));
            request.transferability = KeyTransferability::NonTransferable;
            request
        }
        "salty_multisig" => {
            let mut request = CreateIdentifierRequest::new(salty(&fixture.provenance.multisig_bran, 3, 3));
            request.signing_threshold = Some(SigningThreshold::numeric(2));
            request.next_threshold = Some(SigningThreshold::numeric(2));
            request
        }
        "salty_weighted" => {
            let mut request = CreateIdentifierRequest::new(salty(&case.bran, 2, 2));
            request.signing_threshold = Some(SigningThreshold::from_sith(r#"["1/2","1/2"]"#)?);
            request.next_threshold = Some(SigningThreshold::from_sith(r#"["1/2","1/2"]"#)?);
            request
        }
        other => return Err(format!("unknown creation case {other:?}").into()),
    };
    match case.name.as_str() {
        "salty_witnessed" => {
            request.witnesses = fixture
                .provenance
                .witnesses
                .iter()
                .map(|witness| IdentifierPrefix::from_qb64(witness))
                .collect::<Result<Vec<_>, _>>()?;
            request.witness_threshold = 2;
        }
        "salty_delegated_with_data" => {
            request.delegator = Some(IdentifierPrefix::from_qb64(&fixture.provenance.delegator)?);
            // Built with explicit inserts: the seal's field order is committed into the SAID.
            let mut seal = Sad::new();
            seal.insert("i", fixture.provenance.delegator.clone())?;
            seal.insert("s", "0".to_owned())?;
            seal.insert("d", fixture.provenance.delegator.clone())?;
            request.anchor = Some(seal);
        }
        _ => {}
    }
    Ok(request)
}

/// Rebuilds a stored salty identifier record so the factory can reload its keeper.
///
/// The fixture records the salt a keeper's sealed `sxlt` opened to; the Rust side seals it again
/// to the same controller key, which is what the reference's stored record carries.
fn salty_hab(bran: &str, state: &KeyState, params: &Value) -> Result<Hab, Box<dyn Error>> {
    let (encrypter, _) = sealing_keys(bran)?;
    let opens_to = params
        .get("sxlt_opens_to")
        .and_then(Value::as_str)
        .ok_or("the recorded parameters hold no salt")?;
    let sealed = encrypter
        .encrypt_salt(&Salt::from_qb64(opens_to, SecurityTier::Low)?)?
        .qb64()?;
    let mut salty = params.clone();
    let object = salty.as_object_mut().ok_or("the parameters are not an object")?;
    object.remove("sxlt_opens_to");
    object.insert("sxlt".to_owned(), Value::from(sealed));
    Ok(serde_json::from_value(serde_json::json!({
        "name": "aid1",
        "prefix": state.identifier,
        "icp_dt": "2023-12-01T10:05:25.062609+00:00",
        "salty": salty,
        "state": serde_json::to_value(state)?,
    }))?)
}

#[test]
fn the_manifest_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert!(fixture.upstream.contains("WebOfTrust/signify-ts"));
    assert_ne!(fixture.generated_on, "");
    assert!(fixture.sources.iter().any(|source| source.ends_with("aiding.ts")));
    assert_ne!(fixture.provenance.note, "");
    assert_ne!(fixture.provenance.member_two_bran, "");
    assert_eq!(fixture.provenance.witnesses.len(), 3);
    assert_eq!(fixture.creations.len(), 6);
    for case in &fixture.creations {
        assert_eq!(case.request.path, "/identifiers", "{}", case.name);
        assert_eq!(case.request.method, "POST", "{}", case.name);
        assert!(case.request.name.is_some(), "{}", case.name);
        assert_ne!(case.kargs_note, "");
    }
    // The reply records carry the parsed reply beside its exact text; both must agree.
    for record in [
        &fixture.replies.end_role,
        &fixture.replies.end_role_without_eid,
        &fixture.replies.location_scheme,
        &fixture.replies.location_scheme_defaults,
    ] {
        let reparsed: Value = serde_json::from_str(&record.rpy_raw)?;
        assert_eq!(reparsed, record.rpy);
    }
    assert_ne!(
        fixture
            .reference_quirks
            .create_wraps_data_even_when_it_is_a_list
            .rust_decision,
        ""
    );
    Ok(())
}

/// Reproduces one creation case at the reference's own production Argon2 cost.
fn assert_creation_case(name: &str) -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let case = fixture
        .creations
        .iter()
        .find(|case| case.name == name)
        .ok_or_else(|| format!("the fixture has no case named {name:?}"))?;
    let request = creation_request(&fixture, case)?;
    let factory = factory(&case.bran)?;
    let mut keeper = factory.create(request.keeper_request(0)?)?;
    let artifact = incept_identifier(keeper.as_mut(), &request)?;
    assert_artifact_matches(&artifact, &case.request)?;
    assert_eq!(case.request.algorithm.as_deref(), Some("salty"));
    let params = case.request.params.as_ref().ok_or("the case records no parameters")?;
    // The keeper's own salt may come from another bran, but it always seals to the client
    // controller's key, which derives from the case's bran.
    assert_salty_params(keeper.as_ref(), &case.bran, params)?;
    assert_eq!(request.member_identifiers(), case.request.smids);
    assert_eq!(request.rotation_member_identifiers(), case.request.rmids);
    Ok(())
}

macro_rules! creation_tests {
    ($($test_name:ident => $case:literal,)*) => {
        $(
            #[test]
            fn $test_name() -> Result<(), Box<dyn Error>> {
                assert_creation_case($case)
            }
        )*
    };
}

creation_tests! {
    creation_salty_default => "salty_default",
    creation_salty_non_transferable => "salty_non_transferable",
    creation_salty_multisig => "salty_multisig",
    creation_salty_witnessed => "salty_witnessed",
    creation_salty_delegated_with_data => "salty_delegated_with_data",
    creation_salty_weighted => "salty_weighted",
}

#[test]
fn a_randy_creation_reproduces_the_recorded_shape() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let shape = &fixture.randy_shape;
    assert_ne!(shape.note, "");

    let request = CreateIdentifierRequest::new(CreateAlgorithm::randy());
    let factory = factory(&fixture.provenance.bran)?;
    let mut keeper = factory.create(request.keeper_request(0)?)?;
    let artifact = incept_identifier(keeper.as_mut(), &request)?;

    assert_eq!(artifact.event.sad().get_text("s"), Some(shape.sequence.as_str()));
    assert_eq!(
        artifact.event.sad().get_text("kt"),
        Some(shape.signing_threshold.as_str())
    );
    let keys = artifact.event.serialized().verification_keys()?;
    assert_eq!(keys.len(), shape.key_count);
    let first = keys
        .first()
        .map(keri_cesr::crypto::verifier::VerificationKey::qb64)
        .transpose()?
        .unwrap_or_default();
    assert!(first.starts_with(&shape.key_code));
    assert!(artifact.event.identifier().qb64()?.starts_with(&shape.pre_code));
    assert_eq!(artifact.signatures.qb64()?.len(), shape.sig_count);

    let KeyManagerState::Randy(randy) = keeper.parameters()? else {
        return Err("the keeper did not report randy parameters".into());
    };
    assert_eq!(randy.encrypted_signing_keys.len(), shape.prxs_count);
    assert_eq!(randy.encrypted_next_keys.len(), shape.nxts_count);
    assert!(shape.transferable);
    Ok(())
}

#[test]
fn the_group_creation_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let group = &fixture.group_creation;

    // The local member's record, with its salt resealed to the client controller's key.
    let member1_state: KeyState =
        serde_json::from_value(group.members.member1.get("state").cloned().ok_or("no member state")?)?;
    let member1 = salty_hab(
        &fixture.provenance.bran,
        &member1_state,
        group
            .members
            .member1
            .get("salty")
            .ok_or("the member records no salty parameters")?,
    )?;
    let Hab::Accepted(member1) = member1 else {
        return Err("the member parsed as pending".into());
    };
    let member2_state: KeyState =
        serde_json::from_value(group.members.member2.get("state").cloned().ok_or("no member state")?)?;
    let member3_state: KeyState =
        serde_json::from_value(group.members.member3.get("state").cloned().ok_or("no member state")?)?;

    let mut request = CreateIdentifierRequest::new(CreateAlgorithm::Group {
        member: Box::new(member1),
        states: vec![member1_state.clone(), member2_state.clone()],
        next_states: vec![member2_state, member3_state],
    });
    request.signing_threshold = Some(SigningThreshold::numeric(1));
    request.next_threshold = Some(SigningThreshold::numeric(1));

    let factory = factory(&fixture.provenance.bran)?;
    let mut keeper = factory.create(request.keeper_request(0)?)?;
    let artifact = incept_identifier(keeper.as_mut(), &request)?;
    assert_artifact_matches(&artifact, &group.request)?;
    assert_eq!(request.member_identifiers(), group.request.smids);
    assert_eq!(request.rotation_member_identifiers(), group.request.rmids);
    Ok(())
}

#[test]
fn every_interaction_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.interactions.len(), 3);
    let default_creation = fixture
        .creations
        .iter()
        .find(|case| case.name == "salty_default")
        .ok_or("the fixture has no default creation")?;
    let params = default_creation
        .request
        .params
        .as_ref()
        .ok_or("the default creation records no parameters")?;

    for case in &fixture.interactions {
        let hab = salty_hab(&fixture.provenance.bran, &case.state, params)?;
        let keeper = factory(&fixture.provenance.bran)?.keeper_for(&hab)?;

        if case.data.is_some() {
            // The reference embeds the data argument verbatim as the event's anchors, so the
            // recorded event text — parsed order-preservingly — supplies the exact input; a
            // parsed JSON map would have lost the field order the SAID commits to.
            let event_sad = Sad::from_json_bytes(case.request.event_raw.as_bytes())?;
            let anchors = match event_sad.get("a") {
                Some(keri_protocol::serialization::SadValue::Array(items)) => items
                    .iter()
                    .map(|item| match item {
                        keri_protocol::serialization::SadValue::Map(sad) => Ok(sad.clone()),
                        other => Err(format!("a recorded anchor is not a field map: {other:?}")),
                    })
                    .collect::<Result<Vec<_>, _>>()?,
                other => return Err(format!("the recorded event has no anchor list: {other:?}").into()),
            };
            let artifact = interact_identifier(keeper.as_ref(), &case.state, anchors)?;
            assert_artifact_matches(&artifact, &case.request).map_err(|error| format!("{}: {error}", case.name))?;
        } else {
            // The reference anchors `[null]`, which a field-map anchor cannot express; the
            // divergence is that Rust writes an empty list, and the events differ.
            assert_eq!(
                case.request.event.get("a"),
                Some(&serde_json::json!([null])),
                "{}",
                case.name
            );
            let artifact = interact_identifier(keeper.as_ref(), &case.state, Vec::new())?;
            let empty = keri_protocol::serialization::SadValue::Array(Vec::new());
            assert_eq!(artifact.event.sad().get("a"), Some(&empty));
            assert_ne!(artifact.event.raw(), case.request.event_raw.as_bytes());
        }
    }
    Ok(())
}

/// Reproduces one rotation case at production cost.
fn assert_rotation_case(name: &str) -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let case = fixture
        .rotations
        .iter()
        .find(|case| case.name == name)
        .ok_or_else(|| format!("the fixture has no rotation named {name:?}"))?;

    // The stored record: the state's own key parameters, at the key index its creation left.
    let default_creation = fixture
        .creations
        .iter()
        .find(|creation| creation.bran == case.bran || creation.name == "salty_default")
        .ok_or("no creation to borrow parameters from")?;
    let mut params = default_creation
        .request
        .params
        .clone()
        .ok_or("the creation records no parameters")?;
    // The mock state derives its own keeper, so its parameters mirror its own counts.
    let object = params.as_object_mut().ok_or("the parameters are not an object")?;
    object.insert(
        "icodes".to_owned(),
        serde_json::json!(vec!["A"; case.state.signing_keys.len()]),
    );
    object.insert(
        "ncodes".to_owned(),
        serde_json::json!(vec!["A"; case.state.next_key_digests.len()]),
    );
    // A bran-backed keeper's own salt is the bran salt itself, which the fixture's recorded
    // `sxlt_opens_to` values confirm.
    object.insert(
        "sxlt_opens_to".to_owned(),
        Value::from(format!("0AA{}", &case.bran[..21])),
    );

    let hab = salty_hab(&case.bran, &case.state, &params)?;
    let mut keeper = factory(&case.bran)?.keeper_for(&hab)?;

    let mut request = RotateIdentifierRequest::default();
    if let Some(count) = case.args.get("ncount").and_then(Value::as_u64) {
        request.next_count = usize::try_from(count)?;
    }
    if let Some(sith) = case.args.get("nsith").and_then(Value::as_str) {
        request.next_threshold = Some(SigningThreshold::from_sith(sith)?);
    }
    if let Some(toad) = case.args.get("toad").and_then(Value::as_u64) {
        request.witness_threshold = Some(u32::try_from(toad)?);
    }
    if let Some(cuts) = case.args.get("cuts").and_then(Value::as_array) {
        request.witness_cuts = cuts
            .iter()
            .filter_map(Value::as_str)
            .map(IdentifierPrefix::from_qb64)
            .collect::<Result<Vec<_>, _>>()?;
    }
    if let Some(adds) = case.args.get("adds").and_then(Value::as_array) {
        request.witness_adds = adds
            .iter()
            .filter_map(Value::as_str)
            .map(IdentifierPrefix::from_qb64)
            .collect::<Result<Vec<_>, _>>()?;
    }

    let artifact = rotate_identifier(keeper.as_mut(), &case.state, &request)?;
    assert_artifact_matches(&artifact, &case.request).map_err(|error| format!("{name}: {error}").into())
}

macro_rules! rotation_tests {
    ($($test_name:ident => $case:literal,)*) => {
        $(
            #[test]
            fn $test_name() -> Result<(), Box<dyn Error>> {
                assert_rotation_case($case)
            }
        )*
    };
}

rotation_tests! {
    rotation_salty_default => "salty_default",
    rotation_hexadecimal_sequence => "hexadecimal_sequence",
    rotation_delegated => "delegated",
    rotation_witness_changes => "witness_changes",
    rotation_explicit_next_threshold => "explicit_next_threshold",
}

#[test]
fn every_reply_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let controller = IdentifierPrefix::from_qb64(&fixture.replies.prefix)?;
    let delegator = IdentifierPrefix::from_qb64(&fixture.provenance.delegator)?;
    let stamp = Timestamp::parse(&fixture.provenance.stamp)?;

    let end_role = end_role_reply(&controller, &Role::Agent, Some(&delegator), stamp.clone())?;
    assert_eq!(end_role.raw(), fixture.replies.end_role.rpy_raw.as_bytes());
    let bare = end_role_reply(&controller, &Role::Agent, None, stamp.clone())?;
    assert_eq!(bare.raw(), fixture.replies.end_role_without_eid.rpy_raw.as_bytes());

    let endpoint = IdentifierPrefix::from_qb64("EHgwVwQT15OJvilVvW57HE4w0-GPs_Stj2OFoAHZSysY")?;
    let location = location_scheme_reply(
        &controller,
        "https://test.com",
        Some("https"),
        Some(&endpoint),
        stamp.clone(),
    )?;
    assert_eq!(location.raw(), fixture.replies.location_scheme.rpy_raw.as_bytes());
    let defaults = location_scheme_reply(&controller, "http://test.com", None, None, stamp)?;
    assert_eq!(
        defaults.raw(),
        fixture.replies.location_scheme_defaults.rpy_raw.as_bytes()
    );

    // The signatures come from the identifier's keeper, reloaded from the default creation.
    let default_creation = fixture
        .creations
        .iter()
        .find(|case| case.name == "salty_default")
        .ok_or("the fixture has no default creation")?;
    let params = default_creation
        .request
        .params
        .as_ref()
        .ok_or("the default creation records no parameters")?;
    let interaction = fixture
        .interactions
        .first()
        .ok_or("the fixture records no interactions")?;
    let hab = salty_hab(&fixture.provenance.bran, &interaction.state, params)?;
    let keeper = factory(&fixture.provenance.bran)?.keeper_for(&hab)?;
    let signed = sign_reply(keeper.as_ref(), &end_role)?;
    assert_eq!(signed.signatures.qb64()?, fixture.replies.end_role.sigs);
    assert_eq!(fixture.replies.end_role.path, "/identifiers/aid1/endroles");
    assert_eq!(fixture.replies.end_role.method, "POST");
    assert_eq!(fixture.replies.location_scheme.path, "/identifiers/aid1/locschemes");
    Ok(())
}

#[test]
fn every_reference_rejection_is_refused_here_too() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejections.len(), 2);
    for rejection in &fixture.rejections {
        assert!(!rejection.reference_error_message.is_empty(), "{}", rejection.name);
        assert!(!rejection.note.is_empty(), "{}", rejection.name);
        match rejection.name.as_str() {
            "witnessed_without_toad" => {
                let mut request =
                    CreateIdentifierRequest::new(CreateAlgorithm::salty(Some(fixture.provenance.bran.clone().into())));
                request.witnesses = vec![IdentifierPrefix::from_qb64(
                    fixture
                        .provenance
                        .witnesses
                        .first()
                        .ok_or("the fixture records no witnesses")?,
                )?];
                assert!(matches!(request.keeper_request(0), Err(IdentifierError::Event { .. })));
            }
            "unknown_external_module" => {
                let request = CreateIdentifierRequest::new(CreateAlgorithm::Extern {
                    module_type: "hsm".to_owned(),
                    parameters: serde_json::Map::new(),
                });
                let outcome = factory(&fixture.provenance.bran)?.create(request.keeper_request(0)?);
                assert!(matches!(
                    outcome.map(|_| ()),
                    Err(ManagerError::UnknownExternalModule { .. })
                ));
            }
            other => return Err(format!("unknown rejection case {other:?}").into()),
        }
    }
    Ok(())
}

#[test]
fn the_reference_quirks_hold_and_the_divergences_are_deliberate() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // The silent non-transferable rewrites: the reference ignores explicit contradictions; Rust
    // refuses them, which the unit tests assert against each variant.
    assert!(
        quirks
            .non_transferable_rewrites_are_silent
            .overridden_arguments_change_nothing
    );
    assert_ne!(quirks.non_transferable_rewrites_are_silent.note, "");
    assert_ne!(quirks.non_transferable_rewrites_are_silent.rust_decision, "");

    // The `[null]` anchor and the double-wrapped list are unrepresentable here.
    assert_ne!(quirks.interact_without_data_anchors_null.rust_decision, "");
    assert!(quirks.create_wraps_data_even_when_it_is_a_list.nested);
    assert!(
        quirks
            .create_wraps_data_even_when_it_is_a_list
            .anchors
            .get(0)
            .and_then(Value::as_array)
            .is_some()
    );
    assert_ne!(quirks.create_wraps_data_even_when_it_is_a_list.note, "");
    assert_ne!(quirks.unused_create_arguments.note, "");
    assert_ne!(quirks.unused_create_arguments.rust_decision, "");
    assert_ne!(quirks.end_role_default_stamp_reads_the_clock.note, "");
    assert_ne!(quirks.end_role_default_stamp_reads_the_clock.rust_decision, "");
    Ok(())
}
